ame":"Milch","quantity":100,"unit":"ml"},{"id":"potato","name":"Kartoffeln","quantity":400,"unit":"g"}],"primary_side":"potato","dish_type":"auflauf","main_ingredient":"brokkoli","preparation_method":"backen","flavors":["cremig"]},{"id":"example-20","expected_name":"Linsen-Bolognese","expected_minutes":35,"expected_servings":2,"expected_steps_hash":"2a9f4b8801f82b69d4b6e8b57f76634e","expected_ingredients":[{"id":"carrot","name":"Karotten","quantity":150,"unit":"g"},{"id":"lentils","name":"Rote Linsen","quantity":120,"unit":"g"},{"id":"oil","name":"Olivenöl","quantity":15,"unit":"ml"},{"id":"onion","name":"Zwiebel","quantity":1,"unit":"Stück"},{"id":"passata","name":"Passierte Tomaten","quantity":400,"unit":"ml"},{"id":"pasta","name":"Nudeln","quantity":200,"unit":"g"},{"id":"stock","name":"Gemüsebrühe","quantity":250,"unit":"ml"}],"primary_side":"pasta","dish_type":"pasta","main_ingredient":"rote linsen","preparation_method":"köcheln","flavors":[]}]$planning_data$::jsonb) as c(
    id text,expected_name text,expected_minutes integer,expected_servings integer,
    expected_steps_hash text,expected_ingredients jsonb,primary_side text,
    dish_type text,main_ingredient text,preparation_method text,flavors jsonb
  )
)
update public.recipes r set
  primary_side=coalesce(nullif(trim(r.primary_side),''),c.primary_side),
  dish_type=coalesce(nullif(trim(r.dish_type),''),c.dish_type),
  main_ingredient=coalesce(nullif(trim(r.main_ingredient),''),c.main_ingredient),
  preparation_method=coalesce(nullif(trim(r.preparation_method),''),c.preparation_method),
  flavors=case when cardinality(r.flavors)=0 then array(select jsonb_array_elements_text(c.flavors)) else r.flavors end
from curated c
where r.id=c.id and r.name=c.expected_name
  and r.prep_minutes=c.expected_minutes and r.servings=c.expected_servings
  and r.is_published and r.deleted_at is null
  and md5(array_to_string(r.steps,chr(10)))=c.expected_steps_hash
  and (select jsonb_agg(jsonb_build_object('id',ri.ingredient_id,'name',i.name,'quantity',ri.quantity,'unit',ri.unit)
      order by ri.ingredient_id collate "C",ri.unit collate "C")
    from public.recipe_ingredients ri join public.ingredients i on i.id=ri.ingredient_id where ri.recipe_id=r.id)=c.expected_ingredients
  and (nullif(trim(r.primary_side),'') is null or nullif(trim(r.dish_type),'') is null
    or (nullif(trim(r.main_ingredient),'') is null and c.main_ingredient is not null)
    or nullif(trim(r.preparation_method),'') is null
    or (cardinality(r.flavors)=0 and jsonb_array_length(c.flavors)>0))
returning r.id,r.name,r.primary_side,r.dish_type,r.main_ingredient,r.preparation_method,r.flavors;
commit;
